for l in L_[125:162]:
    c=[x.strip() for x in l.strip("|").split("|")]
    t2.append((l,c))
# full genus map
gen={}
for n in t1:
    if not re.match(r"^[A-Z]\.",n): gen[n.split()[0]]=n.split()[0]
def full(n,prev=[None]):
    return n
last={}
for n in t1:
    g,s=n.split()[0],n.split()[1]
    last[g[0]]=last.get(g[0],[])
# map abbreviation by preceding full name in table 1 order
fullname={}
cur=None
for n in t1:
    if re.match(r"^[A-Z]\.",n):
        fullname[n]=cur+" "+n.split()[1]
    else:
        cur=n.split()[0]; fullname[n]=n
# table 2 names: abbreviated "A. minor", "T. shiressii", "B. serrata" use same mapping
sites=["A","B","C","D"]
src="benson, d. h. (1985). maturation periods for fire-sensitive shrub species in hawkesbury sandstone vegetation. cunninghamia, 1(3), 339-349."
siteinfo={"A":("site a",-33.5,151.25,1250,"summer"),"B":("site b",-33.5,151.25,1250,"summer"),"C":("site c",-33.5,151.25,1250,"summer"),"D":("site d",-33.5,151.25,1250,"summer"),"G":("",-33.5833,151,930,"summer")}
rows=[];parsed=[]
for l,c in t2:
    name=c[0]; a,b,cc,d,bwv,g,gv=c[1:8]
    vals={"A":a,"B":b,"C":cc,"D":d,"G":g}
    fam,code=t1[name]
    fn=fullname[name]; genus,sp=fn.split()
    vic={"BW":bwv,"G":gv}
