        if not v: continue
        v=v.lstrip("*")
        m=re.match(r"^(\d+)(?:\((\d+)\))?$",v)
        if v=="no flowering yet": first=">8"; fifty=""
        elif m: first=m.group(1); fifty=m.group(2) or ""
        else: raise SystemExit("bad "+v+name)
        loc,lat,lon,rain,seas=siteinfo[k]
        resp={"fs":"obligate","fs*":"obligate","r":"resprouter","?fs":"?fs"}[code]
        n=["table 2, p. 342"]
        n.append("age_at_first_flower_production_from_seed_repr3 is the number of years to first flowering after fire of marked seedlings (maturation time, germination to flowering)" if first!=">8" else "age_at_first_flower_production_from_seed_repr3 >8 from 'no flowering yet' at last recording, eight years of three-monthly recordings after fire (p. 340, p. 345)")
        if fifty: n.append("time_to_50_percent_flowering from the bracketed value: years to at least 50 per cent of individuals flowering, given where 10 or more individuals were marked at the site (table 2 footnote)")
        vv=vic["G"] if k=="G" else vic["BW"]
        if vv: n.append("plants in the vicinity first flowered after %s years (table 2, not entered: many were unaffected by the fire, p. 345)"%vv)
        n.append("fire_response_categorical_surv1 from table 1, p. 341: code '%s' (fs = fire-sensitive; r = resprouter; ? = probably fire-sensitive)"%code + ("; fs* footnote: beadle (1940) states a lignotuber and 92 per cent survival, not the case at the study sites" if code=="fs*" else ""))
        if name!=fn: n.append("species printed as '%s' in tables"%name)
        if k=="G": n.append("glenorie site: woodland on dry ridgetop, burnt january 1975 (fire_season_categorical derived from date); average rainfall 930 mm per annum; second locality studied to check a lower rainfall")
        else: n.append("brisbane water national park: hot summer (1974-75) fire six months before first observations, fire_severity_categorical 'hot' as printed; rainfall about 1250 mm per annum; four sites within about 0.5 km, coordinates for the main study locality; seedlings marked in a transect of 10 plots per site; a low-intensity fire burnt half of the site a transect in july-august 1980")
        n.append("flowering recorded four times a year for eight years")
        rows.append(dict(genus=genus,species=sp,scientific_name=f"{genus} {sp}",family=fam.lower(),fire_response_categorical_surv1=resp,age_at_first_flower_production_from_seed_repr3=first,time_to_50_percent_flowering=fifty,time_unit="years" if fifty else "",location_name=loc,latitude=str(lat),longitude=str(lon),rainfall_mm=str(rain),fire_season_categorical=seas,fire_severity_categorical="" if k=="G" else "hot",notes="; ".join(n),source=src,file_name="Benson 1985 Cunninghamia_primary juvenile period"))
        parsed.append((l,k,rows[-1]))
if __name__=="__main__":
    print(len(rows))
    for l,k,r in random.sample(parsed,3):
        print(l[:150]); print(k,r['scientific_name'],r['family'],r['fire_response_categorical_surv1'],r['age_at_first_flower_production_from_seed_repr3'],r['time_to_50_percent_flowering'],r['location_name'])
