import sys,re,random; sys.path.insert(0,'.')
from h import *
P="/home/jess/Documents/primary_juvenile_meta-analysis/data/papers_test/md_agents/Knox_&_Clarke_2004_Cunninghamia_primary_juvenile_period.md"
L_=open(P).read().split("\n")
def cells(l): return [re.sub(r"\s+"," ",c).strip() for c in re.findall(r"<t[dh]>(.*?)</t[dh]>",l)]
def rowsof(line): return [cells(r) for r in re.findall(r"<tr>(.*?)</tr>",line)[1:]]
t1={r[0]:r for r in rowsof(L_[72])}
t2={r[0]:r for r in rowsof(L_[90])}
src="knox, k. j. e., & clarke, p. j. (2004). fire response syndromes of shrubs in grassy woodlands in the new england tableland bioregion. cunninghamia, 8(3), 348-353."
stem="Knox_&_Clarke_2004_Cunninghamia_primary_juvenile_period"
def val(s):
    s=s.replace("&lt;","<").strip()
    if s in("*",""): return None
    m=re.match(r"^Not flowering after ([\d.]+) years$",s)
    if m: return ">"+m.group(1)
    m=re.match(r"^(<)\s*([\d.]+) years$",s)
    if m: return "<"+m.group(2)
    m=re.match(r"^([\d.]+) years$",s)
    if m: return m.group(1)
    if s=="n.a.": return None
    raise SystemExit("bad "+s)
def name(n):
    n=n.replace(" .",".")
    m=re.match(r"^(\w+) (sp\. nov|sp\. aff\. \w+)$",n)
    if m: return m.group(1),m.group(2),"",n
    m=re.match(r"^(\w+) (\w+) (subsp\.|var\.) (\w+)$",n)
    if m: return m.group(1),m.group(2),m.group(3)+" "+m.group(4),n
    m=re.match(r"^(\w+) (\w+)$",n)
    return m.group(1),m.group(2),"",n
mode={"basal/lignotuber":"basal; lignotuber","suckers/epicormic":"sucker; epicormic","suckers/basal":"sucker; basal","suckers":"sucker"}
rows=[]; parsed=[]
for n in t2:
    r2=t2[n]; r1=t1.get(n)
    g,s,ss,pr=name(n)
    resp="obligate" if r2[1]=="obligate seeder" else "resprouter"
    pjp=val(r2[2]); sjp=val(r2[3])
    notes=["table 2, p. 351"]
    if r1: notes.append("table 1, p. 350: survival %s%% (n=%s), mode of resprouting printed as '%s'"%(r1[2],r1[3].strip("()"),r1[4]))
    else: notes.append("species not in table 1")
    if pjp and pjp.startswith(">"): notes.append("primary_juvenile_period not flowering after %s years (last observation)"%pjp[1:])
    if sjp and sjp.startswith(">"): notes.append("secondary_juvenile_period not flowering after %s years (last observation)"%sjp[1:])
    if sjp and sjp.startswith("<"): notes.append("secondary_juvenile_period printed as less than %s years"%sjp[1:])
    if n.endswith("setulosai"): notes.append("name printed as 'setulosai'")
    if " sp. " in n: notes.append("name printed as '%s'"%n.lower())
    notes.append("fire_response_categorical_surv1: obligate seeders = less than 30% of individuals survived 100% leaf scorch, resprouters = more than 70% (p. 349); fire response three years after experimental burns; juvenile periods from sites 1.5-3 years post-fire and from sown seed (p. 350)")
    notes.append("species not assigned to a site in the paper: imbota nature reserve (burnt spring 1999, average yearly rainfall 790 mm) and booroolong nature reserve (burnt autumn 2000, rainfall 884 mm at nearby guyra); fire intensity not measured (moderate and low expected in high and low fuel areas); shrub species with fire_season and severity per site not given")
    mt=r1[4] if r1 else ""
    rows.append(dict(genus=g,species=s,subsp=ss,scientific_name=f"{g} {s}",fire_response_categorical_surv1=resp,resprouter_type=mode.get(mt,"") if resp=="resprouter" else "",primary_juvenile_period=pjp or "",secondary_juvenile_period=sjp or "",time_unit="years" if sjp else "",location_name="imbota nature reserve; booroolong nature reserve",fire_type="experimental burn",fire_season_categorical="autumn; spring",notes="; ".join(notes),source=src,file_name=stem))
    parsed.append((n,r1,r2,rows[-1]))
if __name__=="__main__":
    print(len(rows))
    for n,r1,r2,r in random.sample(parsed,3):
        print(n,r1 and r1[1:],r2[1:]); print({k:r[k] for k in('genus','species','subsp','fire_response_categorical_surv1','resprouter_type','primary_juvenile_period','secondary_juvenile_period')})
