import re
def clean(s):
    s=s.replace("<u>","").replace("</u>","")
    s=s.replace("**","").replace("–","-").replace("–","-")
    return re.sub(r"\s+"," ",s).strip()
NUM=r"\d+(?:\.\d+)?"
def parse(raw):
    """return (kind, lo, hi, unit, note) ; kind in value/none/text"""
    underlined="<u>" in raw
    s=clean(raw)
    if not s: return None
    if underlined: return ("underlined",s)
    # plain value patterns
    m=re.match(r"^(c\.\s*)?(\?)?("+NUM+r")(?:-("+NUM+r"))?\s*([wy])(\?)?(.*)$",s)
    if m:
        c,q,a,b,u,q2,rest=m.groups()
        return ("value",a,b,u,rest.strip(),bool(c),bool(q or q2))
    return ("text",s)
