def clean(s):
    s=s.replace("<u>","").replace("</u>","")
    s=s.replace("**","").replace("–","-").replace("\u2013","-")
    return re.sub(r"\s+"," ",s).strip()
NUM=r"\d+(?:\.\d+)?"
def parse(raw):
    """return (kind, lo, hi, unit, note) ; kind in value/none/text"""
    underlined="<u>" in raw
