cd /tmp/claude-1000/-home-jess-Documents-primary-juvenile-meta-analysis/65379324-54a2-446c-bde3-950b5c339b1a/scratchpad; cat > nsw_build.py <<'E'
import sys,re,collections,random; sys.path.insert(0,'.')
from nsw_parse import reg,va
stem="nswfrrd_v1.3a_pdfvers_sppdata"
def parse_name(s):
    s0=s
    s=s.replace("- ","-").replace("–","-")
    toks=s.split()
    g=toks[0]; rest=toks[1:]
    if rest[0]=="sp." :
        sp=" ".join(rest); sub=""
        return g,sp.lower(),sub,s0
    sp=rest[0]; rest=rest[1:]
    sub=[]
    i=0
    rank={"subsp":"subsp.","subsp.":"subsp.","var":"var.","var.":"var.","forma":"f.","f.":"f.","nothosubsp.":"nothosubsp."}
    while i<len(rest):
        t=rest[i]
        if t in rank and i+1<len(rest):
            sub.append(rank[t]+" "+rest[i+1]); i+=2
        else:
            sub.append(t); i+=1
    return g,sp.lower(),(" ".join(sub)).lower(),s0
def build():
    rows=[]
    for (ln,pg,r),(ln2,pg2,v) in zip(reg,va):
        assert r[0]==v[0]
        name,syn,fam,code,comm,seedst,disp,germ,nfrr,addl=r
        g,sp,sub,printed=parse_name(name)
        code=re.sub(r"\s+"," ",code)
        n=["species table, pdf p. %d (regeneration) and p. %d (vital attributes)"%(pg,pg2)]
        n.append("fire response code '%s' as printed, not defined in the document"%code)
        if syn: n.append("synonym printed '%s'"%syn.lower())
        if comm: n.append("comments on regeneration printed '%s'"%comm.lower() if False else "comments on regeneration printed '%s'"%comm)
        tv=[]
        if v[4]: tv.append("primary juvenile printed '%s'"%v[4])
        if v[5]: tv.append("secondary juvenile period printed '%s'"%v[5])
        if tv: n.append("; ".join(tv)+" (unit not stated, so time columns left empty)")
        if printed!=("%s %s"%(g,sp)) and re.search(r"- |sp\.|subsp |var |forma",printed): n.append("name printed as '%s'"%printed)
        rows.append(dict(genus=g,species=sp,subsp=sub,scientific_name=f"{g} {sp}",family=fam.lower(),fire_response_categorical_surv1=code,notes="; ".join(n),source=stem,file_name=stem))
    return rows
if __name__=="__main__":
    rows=build(); print(len(rows))
    random.seed(5)
    for r in random.sample(rows,3): print(r)
    c=collections.Counter((r['scientific_name'],r['subsp']) for r in rows)
    print([k for k,v in c.items() if v>1][:10])
E
